def transform(grid):
    """Recolor complete monochrome row/column separators to color 2."""
    h, w = len(grid), len(grid[0])
    lines = []
    for r in range(h):
        if len(set(grid[r])) == 1:
            lines.append(("row", r, grid[r][0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1:
            lines.append(("col", c, vals[0]))
    out = [row[:] for row in grid]
    for typ, idx, color in lines:
        if typ == "row":
            out[idx] = [2 if x == color else x for x in out[idx]]
        else:
            for r in range(h):
                out[r][idx] = 2
    return out
